612:     g.userData.healthSprite.draw(clamp(g.userData.hp / g.userData.maxHp, 0, 1));
613:     g.userData.healthSprite.sprite.visible = true;
614:     const p = g.position;
615:     for (let i = 0; i < 8; i++) {
616:       this.sparkles.spawn(p.x + (Math.random() - 0.5) * 0.5, p.y + 1.1 + (Math.random() - 0.5) * 0.5, p.z + (Math.random() - 0.5) * 0.5, '#ffcf6a', { speed: 2.5, up: 1.5, life: 0.45, gravity: -8, size: 0.1 });
617:     }
618:     if (g.userData.hp <= 0) {
619:       g.userData.dead = true;
620:       g.userData.deadTimer = 0;
621:       g.userData.healthSprite.sprite.visible = false;
622:       for (let i = 0; i < 22; i++) {
623:         this.debris.spawn(p.x + (Math.random() - 0.5) * 0.6, p.y + 0.8 + Math.random() * 0.8, p.z + (Math.random() - 0.5) * 0.6, i % 3 ? '#4b3b2a' : '#7d3a2c', { speed: 3, up: 2.5, life: 1.1, gravity: -10, size: 0.12 });
624:       }
625:       if (g.userData.enemy.boss) game.onBossDefeated(g);
626:       else game.onEnemyDefeated(g);
627:       return true;
628:     }
629:     return false;
