131:   naturalHeight(x, z) {
132:     const nx = (x + HX) * 0.045;
133:     const nz = (z + HZ) * 0.045;
134:     const broad = fbm(nx, nz, 5, this.seed);
135:     const hills = fbm(nx * 0.45 + 12.7, nz * 0.45 - 8.3, 3, this.seed + 77);
136:     const ridge = fbm((x + HX) * 0.018 + 4.1, (z + HZ) * 0.018 - 2.6, 4, this.seed + 211);
137:     const edge = Math.max(Math.abs(x) / HX, Math.abs(z) / HZ);
138:     let h = 8 + broad * 8 + (hills - 0.5) * 6 + Math.max(0, ridge - 0.54) * 26;
139:     h += Math.pow(edge, 3.2) * 11;
140:     const river = 37 + 4.2 * Math.sin(z * 0.085) + 3.1 * Math.sin(z * 0.19 + 1.1);
141:     const dist = Math.abs(x - river);
142:     if (dist < 5.5) h -= (5.5 - dist) * 1.85;
143:     if (dist < 2.5) h -= 1.2;
144:     return clamp(Math.round(h), 3, 31);
145:   }
