287:   plantTrees() {
288:     for (let z = -HZ + 3; z < HZ - 3; z++) {
289:       for (let x = -HX + 3; x < HX - 3; x++) {
290:         const h = this.heights[this.hidx(x, z)];
291:         if (h <= SEA_LEVEL + 1) continue;
292:         if (this.getBlock(x, h, z) !== B.GRASS) continue;
293:         if (this.inSite(x, z, 3)) continue;
294:         const forest = fbm((x + HX) * 0.055 + 3.7, (z + HZ) * 0.055 - 9.1, 4, this.seed + 909);
295:         const p = clamp((forest - 0.46) * 0.5, 0, 0.14);
296:         if (hash3(x, z, 3, this.seed) > p) continue;
297:         const type = hash3(x, z, 9, this.seed + 4);
298:         if (type > 0.78) this.placePine(x, h + 1, z);
299:         else if (type > 0.64) this.placeBirch(x, h + 1, z);
300:         else this.placeOak(x, h + 1, z);
301:       }
302:     }
303:   }
