556:   interact(target, game) {
557:     const { kind, entity } = target;
558:     if (kind === 'npc') {
559:       const npc = entity.userData.npc;
560:       if (npc.role === 'elder') game.talkToElder();
561:       else game.showDialogue(npc.name, npc.role === 'guard' ? 'Keep your blade close, traveller. The Black Knight holds the keep, and brigands have been seen near the old stones.' : 'Blessings on you, traveller. The village has not been the same since the Crown was broken.');
562:       return true;
563:     }
564:     if (kind === 'chest') {
565:       const g = entity;
566:       if (g.userData.open) return false;
567:       g.userData.open = true;
568:       g.userData.chest.opened = true;
569:       game.openChest(g);
570:       return true;
571:     }
572:     if (kind === 'shard') {
573:       const g = entity;
574:       if (g.userData.collected) return false;
575:       g.userData.collected = true;
576:       g.userData.shard.collected = true;
577:       g.visible = false;
578:       game.collectShard(g);
579:       return true;
580:     }
581:     if (kind === 'campfire') {
582:       game.restAtCampfire(entity);
583:       return true;
584:     }
585:     if (kind === 'shrine') {
586:       game.touchShrine(entity);
587:       return true;
588:     }
589:     return false;
590:   }
