120:   crenellate(x0, z0, x1, z1, y, id) {
121:     for (let x = x0; x <= x1; x++) if ((x - x0) % 2 === 0) {
122:       this.setBlock(x, y, z0, id, false);
123:       this.setBlock(x, y, z1, id, false);
124:     }
125:     for (let z = z0; z <= z1; z++) if ((z - z0) % 2 === 0) {
126:       this.setBlock(x0, y, z, id, false);
127:       this.setBlock(x1, y, z, id, false);
128:     }
129:   }
