305:   placeOak(x, y, z) {
306:     const height = 4 + Math.floor(this.rng.next() * 3);
307:     for (let i = 0; i < height; i++) this.setBlock(x, y + i, z, B.LOG, false);
308:     const top = y + height;
309:     for (let dy = -1; dy <= 2; dy++) {
310:       const r = dy === 2 ? 1 : 2;
311:       for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
312:         if (Math.abs(dx) === r && Math.abs(dz) === r && this.rng.chance(0.55)) continue;
313:         if (dx === 0 && dz === 0 && dy < 2) continue;
314:         if (this.getBlock(x + dx, top + dy, z + dz) === B.AIR) this.setBlock(x + dx, top + dy, z + dz, this.rng.chance(0.18) ? B.LEAVES_DARK : B.LEAVES, false);
315:       }
316:     }
317:   }
