581:   finalizeMeta() {
582:     this.meta.spawn.y = this.groundY(16, 35) + 0.05;
583:     this.meta.spawn.yaw = 0;
584:     this.meta.spawn.pitch = -0.03;
585:     for (const npc of this.meta.npcs) npc.y = this.groundY(npc.x, npc.z) + 0.02;
586:     for (const e of this.meta.enemies) e.y = this.groundY(e.x, e.z) + 0.02;
