12: function box(w, h, d, color, x = 0, y = 0, z = 0, extra = {}) {
13:   const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(color, extra));
14:   m.position.set(x, y, z);
15:   m.castShadow = true;
