56: function healthSprite() {
57:   const c = document.createElement('canvas');
58:   c.width = 160; c.height = 24;
59:   const ctx = c.getContext('2d');
60:   const tex = new THREE.CanvasTexture(c);
61:   tex.colorSpace = THREE.SRGBColorSpace;
62:   const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: true }));
63:   sprite.scale.set(1.35, 0.2, 1);
64:   const draw = (ratio) => {
65:     ctx.clearRect(0, 0, 160, 24);
66:     ctx.fillStyle = 'rgba(8,7,5,.82)';
67:     roundRect(ctx, 2, 4, 156, 16, 5); ctx.fill();
68:     ctx.strokeStyle = 'rgba(217,180,95,.55)'; ctx.lineWidth = 2; ctx.stroke();
69:     ctx.fillStyle = ratio > 0.5 ? '#b53a2a' : '#d18a2e';
70:     roundRect(ctx, 5, 7, 150 * clamp(ratio, 0, 1), 10, 3); ctx.fill();
71:     tex.needsUpdate = true;
72:   };
73:   return { sprite, draw };
74: }
