60:   getBlock(x, y, z) {
61:     x = Math.floor(x); y = Math.floor(y); z = Math.floor(z);
62:     if (y < 0) return B.STONE;
63:     if (!this.inBounds(x, y, z)) return B.AIR;
64:     return this.data[this.index(x, y, z)];
65:   }
