273:     this.paintPath(-30, 12, -18, 4, 2);
274:     this.paintPath(-30, 12, -30, 3, 2);
275:     for (let z = 15; z <= 20; z++) for (let x = 13; x <= 20; x++) this.paintColumn(x, z, B.COBBLE, 3);
276:     for (let z = 12; z <= 14; z++) for (let x = 14; x <= 18; x++) this.paintColumn(x, z, B.COBBLE, 3);
