254: function hash(x, y, z, seed) {
255:   let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(z | 0, 1440662683) ^ Math.imul(seed | 0, 2147483647);
256:   h = Math.imul(h ^ (h >>> 13), 1274126177);
257:   return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
