201: export class EntityManager {
202:   constructor(scene, world) {
203:     this.scene = scene;
204:     this.world = world;
205:     this.npcs = [];
206:     this.enemies = [];
207:     this.chests = [];
208:     this.shards = [];
209:     this.torches = [];
210:     this.campfires = [];
211:     this.debris = new Particles(scene, 600, false);
212:     this.sparkles = new Particles(scene, 320, true);
213:     this.smoke = new Particles(scene, 260, false);
214:     this.glowTex = new THREE.CanvasTexture(makeGlowTexture());
215:     this.glowTex.colorSpace = THREE.SRGBColorSpace;
216:     this.smokeTex = new THREE.CanvasTexture(makeSmokeTexture());
217:     this.time = 0;
