371:       sword.rotation.z = -0.25;
372:       sword.rotation.x = 0.25;
373:       g.add(sword);
374:       if (e.boss) {
375:         g.add(box(0.42, 0.5, 0.12, '#24242b', -0.44, 1.16, 0.1));
376:         const plume = box(0.16, 0.3, 0.5, '#8a2b22', 0, 1.98, -0.1);
377:         plume.rotation.x = -0.3;
