531:       for (let cx = 0; cx < WORLD_X / CHUNK; cx++) {
532:         const { solid, water } = this.buildChunkGeometry(cx, cz);
533:         if (solid) this.group.add(solid);
534:         if (water) this.group.add(water);
535:         this.chunkMeshes.set(`${cx},${cz}`, { solid, water });
536:         done++;
537:         if (done % 4 === 0) {
538:           onProgress(0.82 + (done / total) * 0.15, 'Carving the land into chunks…');
539:           await tick();
540:         }
541:       }
542:     }
