305:   placeOak(x, y, z) {
306:     const height = 4 + Math.floor(this.rng.next() * 3);
307:     for (let i = 0; i < height; i++) this.setBlock(x, y + i, z, B.LOG, false);
308:     const top = y + height;
309:     for (let dy = -1; dy <= 2; dy++) {
310:       const r = dy === 2 ? 1 : 2;
311:       for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
312:         if (Math.abs(dx) === r && Math.abs(dz) === r && this.rng.chance(0.55)) continue;
313:         if (dx === 0 && dz === 0 && dy < 2) continue;
314:         if (this.getBlock(x + dx, top + dy, z + dz) === B.AIR) this.setBlock(x + dx, top + dy, z + dz, this.rng.chance(0.18) ? B.LEAVES_DARK : B.LEAVES, false);
315:       }
316:     }
317:   }
318: 
319:   placePine(x, y, z) {
320:     const height = 6 + Math.floor(this.rng.next() * 4);
321:     for (let i = 0; i < height; i++) this.setBlock(x, y + i, z, B.LOG, false);
322:     for (let i = 0; i < 5; i++) {
323:       const yy = y + height - 1 - i;
324:       const r = i < 2 ? 2 : i < 4 ? 1 : 0;
325:       for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
326:         if (Math.abs(dx) + Math.abs(dz) > r + 1) continue;
327:         if (this.getBlock(x + dx, yy, z + dz) === B.AIR) this.setBlock(x + dx, yy, z + dz, B.LEAVES_DARK, false);
328:       }
329:     }
330:   }
331: 
332:   placeBirch(x, y, z) {
333:     const height = 5 + Math.floor(this.rng.next() * 3);
334:     for (let i = 0; i < height; i++) this.setBlock(x, y + i, z, B.BIRCH_LOG, false);
335:     const top = y + height;
336:     for (let dy = -1; dy <= 1; dy++) {
337:       const r = dy === 1 ? 1 : 2;
338:       for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
339:         if (Math.abs(dx) === r && Math.abs(dz) === r) continue;
340:         if (dx === 0 && dz === 0 && dy < 1) continue;
341:         if (this.getBlock(x + dx, top + dy, z + dz) === B.AIR) this.setBlock(x + dx, top + dy, z + dz, B.LEAVES, false);
342:       }
343:     }
344:   }
