166: function createHumanoid(colors, role) {
167:   const g = new THREE.Group();
168:   const robe = colors.robe, trim = colors.trim;
169:   const body = box(0.56, 0.72, 0.32, robe, 0, 1.08, 0);
170:   const skirt = box(0.64, 0.5, 0.38, robe, 0, 0.58, 0);
171:   const head = box(0.36, 0.36, 0.34, colors.skin || '#c79d70', 0, 1.63, 0);
172:   const hair = box(0.38, 0.12, 0.36, colors.hair || '#4a3826', 0, 1.8, 0);
173:   const armL = box(0.15, 0.58, 0.16, robe, -0.37, 1.12, 0);
174:   const armR = box(0.15, 0.58, 0.16, robe, 0.37, 1.12, 0);
175:   const legL = box(0.19, 0.52, 0.22, colors.legs || '#3a3025', -0.15, 0.29, 0);
176:   const legR = box(0.19, 0.52, 0.22, colors.legs || '#3a3025', 0.15, 0.29, 0);
177:   const belt = box(0.58, 0.1, 0.34, trim, 0, 0.82, 0);
178:   g.add(body, skirt, head, hair, armL, armR, legL, legR, belt);
179:   if (role === 'elder') {
180:     g.add(box(0.3, 0.18, 0.1, '#e8e1cf', 0, 1.49, 0.18));
181:     const staff = box(0.06, 1.6, 0.06, '#5b4227', 0.46, 0.95, 0.05);
182:     staff.rotation.z = -0.08;
183:     g.add(staff);
184:     const gem = new THREE.Mesh(new THREE.OctahedronGeometry(0.11), new THREE.MeshStandardMaterial({ color: '#d9b45f', emissive: '#8f6d31', emissiveIntensity: 0.8, roughness: 0.35 }));
185:     gem.position.set(0.53, 1.78, 0.05);
186:     g.add(gem);
187:   }
188:   if (role === 'guard') {
189:     g.add(box(0.34, 0.42, 0.12, trim, 0, 1.14, 0.23));
190:     g.add(box(0.12, 0.34, 0.12, '#8b8f96', -0.45, 1.22, 0));
191:     g.add(box(0.5, 0.12, 0.2, '#6f757c', -0.45, 1.41, 0));
192:     g.add(box(0.36, 0.16, 0.36, '#5b6067', 0, 1.86, 0));
193:   }
194:   if (role === 'villager') {
195:     g.add(box(0.44, 0.34, 0.1, trim, 0, 1.12, 0.2));
196:   }
197:   g.userData.parts = { armL, armR, legL, legR, head, body };
198:   return g;
199: }
