527:   async buildMeshes(scene, onProgress = () => {}) {
528:     const total = (WORLD_X / CHUNK) * (WORLD_Z / CHUNK);
529:     let done = 0;
530:     for (let cz = 0; cz < WORLD_Z / CHUNK; cz++) {
531:       for (let cx = 0; cx < WORLD_X / CHUNK; cx++) {
532:         const { solid, water } = this.buildChunkGeometry(cx, cz);
533:         if (solid) this.group.add(solid);
534:         if (water) this.group.add(water);
535:         this.chunkMeshes.set(`${cx},${cz}`, { solid, water });
536:         done++;
537:         if (done % 4 === 0) {
538:           onProgress(0.82 + (done / total) * 0.15, 'Carving the land into chunks…');
539:           await tick();
540:         }
541:       }
542:     }
543:   }
544: 
545:   updateChunk(cx, cz) {
546:     if (cx < 0 || cz < 0 || cx >= WORLD_X / CHUNK || cz >= WORLD_Z / CHUNK) return;
547:     const key = `${cx},${cz}`;
548:     const old = this.chunkMeshes.get(key);
549:     if (old) {
550:       for (const m of [old.solid, old.water]) {
551:         if (!m) continue;
552:         this.group.remove(m);
553:         m.geometry.dispose();
554:       }
555:     }
556:     const { solid, water } = this.buildChunkGeometry(cx, cz);
557:     if (solid) this.group.add(solid);
558:     if (water) this.group.add(water);
559:     this.chunkMeshes.set(key, { solid, water });
560:   }
