105:   wallRect(x0, z0, x1, z1, y0, height, id, thickness = 1) {
106:     for (let y = y0; y < y0 + height; y++) {
107:       for (let t = 0; t < thickness; t++) {
108:         for (let x = x0 + t; x <= x1 - t; x++) {
109:           this.setBlock(x, y, z0 + t, id, false);
110:           this.setBlock(x, y, z1 - t, id, false);
111:         }
112:         for (let z = z0 + t; z <= z1 - t; z++) {
113:           this.setBlock(x0 + t, y, z, id, false);
114:           this.setBlock(x1 - t, y, z, id, false);
115:         }
116:       }
