67:   setBlock(x, y, z, id, record = true) {
68:     x = Math.floor(x); y = Math.floor(y); z = Math.floor(z);
69:     if (!this.inBounds(x, y, z)) return false;
70:     this.data[this.index(x, y, z)] = id;
71:     if (record) this.edits.set(`${x},${y},${z}`, id);
72:     return true;
73:   }
