545:   updateChunk(cx, cz) {
546:     if (cx < 0 || cz < 0 || cx >= WORLD_X / CHUNK || cz >= WORLD_Z / CHUNK) return;
547:     const key = `${cx},${cz}`;
548:     const old = this.chunkMeshes.get(key);
549:     if (old) {
550:       for (const m of [old.solid, old.water]) {
551:         if (!m) continue;
552:         this.group.remove(m);
553:         m.geometry.dispose();
554:       }
555:     }
556:     const { solid, water } = this.buildChunkGeometry(cx, cz);
557:     if (solid) this.group.add(solid);
558:     if (water) this.group.add(water);
559:     this.chunkMeshes.set(key, { solid, water });
560:   }
