101:   fillBox(x0, y0, z0, x1, y1, z1, id) {
102:     for (let y = y0; y <= y1; y++) for (let z = z0; z <= z1; z++) for (let x = x0; x <= x1; x++) this.setBlock(x, y, z, id, false);
103:   }
