267:     this.paintPath(-6, 10, -18, 2, 2);
268:     this.paintPath(-18, 2, -18, -4, 2);
269:     this.paintPath(16, 29, 6, 32, 2);
270:     this.paintPath(6, 32, -2, 34, 2);
