279:   inSite(x, z, margin = 0) {
280:     for (const site of this.siteList) {
281:       if (x >= site.cx - site.hw - margin && x <= site.cx + site.hw + margin &&
282:           z >= site.cz - site.hd - margin && z <= site.cz + site.hd + margin) return true;
283:     }
284:     return false;
