150:     await tick();
151:     onProgress(0.16, 'Laying the foundations…');
152:     this.prepareSites();
153:     await tick();
154:     onProgress(0.28, 'Sowing grass and stone…');
155:     this.fillTerrain();
156:     await tick();
157:     onProgress(0.4, 'Paving the old roads…');
158:     this.paintPaths();
159:     await tick();
160:     onProgress(0.52, 'Building the villages and keeps…');
161:     buildAllStructures(this);
162:     await tick();
