545:   updateChunk(cx, cz) {
546:     if (cx < 0 || cz < 0 || cx >= WORLD_X / CHUNK || cz >= WORLD_Z / CHUNK) return;
547:     const key = `${cx},${cz}`;
548:     const old = this.chunkMeshes.get(key);
549:     if (old) {
550:       for (const m of [old.solid, old.water]) {
551:         if (!m) continue;
552:         this.group.remove(m);
553:         m.geometry.dispose();
554:       }
555:     }
556:     const { solid, water } = this.buildChunkGeometry(cx, cz);
557:     if (solid) this.group.add(solid);
558:     if (water) this.group.add(water);
559:     this.chunkMeshes.set(key, { solid, water });
560:   }
561: 
562:   updateBlockMesh(x, z) {
563:     const cx = Math.floor((x + HX) / CHUNK), cz = Math.floor((z + HZ) / CHUNK);
564:     const lx = (x + HX) % CHUNK, lz = (z + HZ) % CHUNK;
565:     this.updateChunk(cx, cz);
566:     if (lx === 0) this.updateChunk(cx - 1, cz);
567:     if (lx === CHUNK - 1) this.updateChunk(cx + 1, cz);
568:     if (lz === 0) this.updateChunk(cx, cz - 1);
569:     if (lz === CHUNK - 1) this.updateChunk(cx, cz + 1);
570:   }
