439:   buildChunkGeometry(cx, cz) {
440:     const x0 = -HX + cx * CHUNK, z0 = -HZ + cz * CHUNK;
441:     const solid = { pos: [], nor: [], uv: [], col: [], idx: [] };
442:     const water = { pos: [], nor: [], uv: [], idx: [] };
443:     const tint = (x, y, z) => 0.93 + hash3(x, y, z, this.seed + 17) * 0.13;
444: 
445:     for (let z = z0; z < z0 + CHUNK; z++) {
446:       for (let x = x0; x < x0 + CHUNK; x++) {
447:         for (let y = 0; y < WORLD_Y; y++) {
448:           const id = this.getBlock(x, y, z);
449:           if (id === B.AIR) continue;
450:           const def = id === B.WATER ? null : (BLOCK_FACES[id] || null);
451:           if (id === B.WATER) {
452:             for (let f = 0; f < 6; f++) {
453:               const face = FACES[f];
454:               const nx = x + face.dir[0], ny = y + face.dir[1], nz = z + face.dir[2];
455:               const nid = this.getBlock(nx, ny, nz);
456:               if (nid !== B.AIR) continue;
457:               const base = water.pos.length / 3;
458:               for (let v = 0; v < 4; v++) {
459:                 const c = face.corners[v];
460:                 const px = x + c[0], py = y + c[1], pz = z + c[2];
461:                 water.pos.push(px, py, pz);
462:                 water.nor.push(face.dir[0], face.dir[1], face.dir[2]);
463:                 if (f === 2) water.uv.push(px * 0.22, pz * 0.22);
464:                 else water.uv.push((px + pz) * 0.22, py * 0.22);
465:               }
466:               water.idx.push(base, base + 1, base + 2, base, base + 2, base + 3);
467:             }
468:             continue;
469:           }
470:           const faces = def;
471:           for (let f = 0; f < 6; f++) {
472:             const face = FACES[f];
473:             const nx = x + face.dir[0], ny = y + face.dir[1], nz = z + face.dir[2];
474:             const nid = this.getBlock(nx, ny, nz);
475:             if (nid !== B.AIR && nid !== B.WATER) continue;
476:             const tile = f === 2 ? def.top : f === 3 ? def.bottom : def.side;
477:             const uv = tileUV(tile);
478:             const base = solid.pos.length / 3;
479:             const t = tint(x, y, z);
480:             for (let v = 0; v < 4; v++) {
481:               const c = face.corners[v];
482:               const px = x + c[0], py = y + c[1], pz = z + c[2];
483:               const s1 = c[face.t[0]] * 2 - 1;
484:               const s2 = c[face.t[1]] * 2 - 1;
485:               const ax = nx, ay = ny, az = nz;
486:               const bx = ax, by = ay, bz = az;
487:               const p1 = [ax, ay, az]; p1[face.t[0]] += s1;
488:               const p2 = [ax, ay, az]; p2[face.t[1]] += s2;
489:               const p3 = [ax, ay, az]; p3[face.t[0]] += s1; p3[face.t[1]] += s2;
490:               const o1 = this.solidForAO(p1[0], p1[1], p1[2]) ? 1 : 0;
491:               const o2 = this.solidForAO(p2[0], p2[1], p2[2]) ? 1 : 0;
492:               const oc = this.solidForAO(p3[0], p3[1], p3[2]) ? 1 : 0;
493:               const ao = (o1 && o2) ? 0 : 3 - (o1 + o2 + oc);
494:               const brightness = face.light * AO_LEVELS[ao] * t;
495:               solid.pos.push(px, py, pz);
496:               solid.nor.push(face.dir[0], face.dir[1], face.dir[2]);
497:               const u = face.uv[v];
498:               solid.uv.push(uv.x0 + u[0] * (uv.x1 - uv.x0), uv.y0 + u[1] * (uv.y1 - uv.y0));
499:               solid.col.push(brightness, brightness, brightness);
500:             }
501:             solid.idx.push(base, base + 1, base + 2, base, base + 2, base + 3);
502:           }
503:         }
504:       }
505:     }
506: 
507:     const make = (data, material, castShadow) => {
508:       if (!data.pos.length) return null;
509:       const g = new THREE.BufferGeometry();
510:       g.setAttribute('position', new THREE.Float32BufferAttribute(data.pos, 3));
511:       g.setAttribute('normal', new THREE.Float32BufferAttribute(data.nor, 3));
512:       g.setAttribute('uv', new THREE.Float32BufferAttribute(data.uv, 2));
513:       if (data.col.length) g.setAttribute('color', new THREE.Float32BufferAttribute(data.col, 3));
514:       g.setIndex(data.idx);
515:       g.computeBoundingSphere();
516:       const m = new THREE.Mesh(g, material);
517:       m.castShadow = castShadow;
518:       m.receiveShadow = true;
519:       return m;
520:     };
521:     return {
522:       solid: make(solid, this.material, true),
523:       water: make(water, this.waterMaterial, false),
524:     };
525:   }
