371:   collectDecorations() {
372:     this.decorations.length = 0;
373:     for (let z = -HZ + 1; z < HZ - 1; z++) {
374:       for (let x = -HX + 1; x < HX - 1; x++) {
375:         const h = this.heights[this.hidx(x, z)];
376:         if (this.getBlock(x, h, z) !== B.GRASS) continue;
377:         if (this.getBlock(x, h + 1, z) !== B.AIR) continue;
378:         const r = hash3(x, z, 31, this.seed);
379:         if (r > 0.38) continue;
