381:         this.decorations.push({
382:           x: x + 0.18 + hash3(x, z, 3, this.seed) * 0.64,
383:           y: h + 1,
384:           z: z + 0.18 + hash3(x, z, 4, this.seed) * 0.64,
385:           type,
386:           rot: hash3(x, z, 5, this.seed) * Math.PI,
387:           scale: 0.75 + hash3(x, z, 6, this.seed) * 0.55,
