572:   applyEdits(edits) {
573:     for (const [key, id] of edits) {
574:       const [x, y, z] = key.split(',').map(Number);
575:       this.setRaw(x, y, z, id);
576:       this.edits.set(key, id);
577:     }
578:     for (let cz = 0; cz < WORLD_Z / CHUNK; cz++) for (let cx = 0; cx < WORLD_X / CHUNK; cx++) this.updateChunk(cx, cz);
579:   }
