324:       const r = i < 2 ? 2 : i < 4 ? 1 : 0;
325:       for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
326:         if (Math.abs(dx) + Math.abs(dz) > r + 1) continue;
