603: BLOCK_FACES[B.DIRT] = { top: TILE.DIRT, bottom: TILE.DIRT, side: TILE.DIRT };
604: BLOCK_FACES[B.STONE] = { top: TILE.STONE, bottom: TILE.STONE, side: TILE.STONE };
605: BLOCK_FACES[B.COBBLE] = { top: TILE.COBBLE, bottom: TILE.COBBLE, side: TILE.COBBLE };
606: BLOCK_FACES[B.LOG] = { top: TILE.LOG_TOP, bottom: TILE.LOG_TOP, side: TILE.LOG_SIDE };
607: BLOCK_FACES[B.PLANKS] = { top: TILE.PLANKS, bottom: TILE.PLANKS, side: TILE.PLANKS };
608: BLOCK_FACES[B.LEAVES] = { top: TILE.LEAVES, bottom: TILE.LEAVES, side: TILE.LEAVES };
