592:   attack(player) {
593:     const pp = player.position;
594:     const fx = -Math.sin(player.yaw), fz = -Math.cos(player.yaw);
595:     let best = null;
596:     for (const g of this.enemies) {
597:       if (g.userData.dead) continue;
598:       const dx = g.position.x - pp.x, dz = g.position.z - pp.z;
599:       const dist = Math.hypot(dx, dz);
600:       if (dist > 3.3) continue;
601:       const dot = (dx * fx + dz * fz) / Math.max(0.001, dist);
602:       if (dot < 0.35) continue;
603:       if (!best || dist < best.dist) best = { g, dist };
604:     }
605:     if (!best) return null;
606:     return best.g;
607:   }
