89:     x = Math.floor(x); z = Math.floor(z);
90:     if (x < -HX || x >= HX || z < -HZ || z >= HZ) return SEA_LEVEL;
91:     for (let y = WORLD_Y - 1; y >= 0; y--) if (isSolid(this.getBlock(x, y, z))) return y;
92:     return 0;
