20: function makeLabel(text, color = '#f2e4c2', bg = 'rgba(18,15,9,.72)', scale = 1) {
21:   const c = document.createElement('canvas');
22:   c.width = 512; c.height = 128;
23:   const ctx = c.getContext('2d');
24:   ctx.clearRect(0, 0, 512, 128);
25:   if (bg) {
26:     ctx.fillStyle = bg;
27:     const w = Math.min(480, ctx.measureText(text).width + 80);
28:     roundRect(ctx, 256 - w / 2, 22, w, 74, 10);
29:     ctx.fill();
30:     ctx.strokeStyle = 'rgba(217,180,95,.35)';
31:     ctx.lineWidth = 2;
32:     ctx.stroke();
33:   }
34:   ctx.font = '600 46px Georgia, serif';
35:   ctx.textAlign = 'center';
36:   ctx.textBaseline = 'middle';
37:   ctx.fillStyle = color;
38:   ctx.fillText(text, 256, 62);
39:   const tex = new THREE.CanvasTexture(c);
40:   tex.colorSpace = THREE.SRGBColorSpace;
41:   const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: true }));
42:   sprite.scale.set(2.4 * scale, 0.6 * scale, 1);
43:   return sprite;
44: }
