245:   paintPath(x0, z0, x1, z1, width = 2, id = B.PATH) {
246:     const dx = x1 - x0, dz = z1 - z0;
247:     const steps = Math.max(Math.abs(dx), Math.abs(dz)) * 2;
248:     const half = width >> 1;
249:     for (let i = 0; i <= steps; i++) {
250:       const t = steps === 0 ? 0 : i / steps;
251:       const x = Math.round(x0 + dx * t), z = Math.round(z0 + dz * t);
252:       for (let oz = -half; oz <= half; oz++) for (let ox = -half; ox <= half; ox++) this.paintColumn(x + ox, z + oz, id);
253:     }
254:   }
