562:   updateBlockMesh(x, z) {
563:     const cx = Math.floor((x + HX) / CHUNK), cz = Math.floor((z + HZ) / CHUNK);
564:     const lx = (x + HX) % CHUNK, lz = (z + HZ) % CHUNK;
565:     this.updateChunk(cx, cz);
566:     if (lx === 0) this.updateChunk(cx - 1, cz);
567:     if (lx === CHUNK - 1) this.updateChunk(cx + 1, cz);
568:     if (lz === 0) this.updateChunk(cx, cz - 1);
569:     if (lz === CHUNK - 1) this.updateChunk(cx, cz + 1);
570:   }
