186:   prepareSites() {
187:     const sites = {
188:       village: { cx: 16, cz: 16, hw: 13, hd: 13, blend: 5, min: 9, max: 13 },
189:       castle: { cx: -18, cz: -18, hw: 16, hd: 16, blend: 6, min: 14, max: 22, force: 2 },
190:       ruins: { cx: 22, cz: -28, hw: 7, hd: 7, blend: 4, min: 7, max: 18 },
191:       stones: { cx: -30, cz: 12, hw: 10, hd: 10, blend: 5, min: 12, max: 20, force: 1 },
192:       camp: { cx: -2, cz: 34, hw: 6, hd: 6, blend: 4, min: 8, max: 16 },
193:     };
194:     for (const site of Object.values(sites)) {
195:       let sum = 0, count = 0;
196:       for (let z = site.cz - site.hd; z <= site.cz + site.hd; z++) for (let x = site.cx - site.hw; x <= site.cx + site.hw; x++) {
197:         sum += this.heights[this.hidx(x, z)]; count++;
198:       }
199:       site.target = clamp(Math.round(sum / count + (site.force || 0)), site.min, site.max);
200:       for (let z = site.cz - site.hd - site.blend; z <= site.cz + site.hd + site.blend; z++) {
201:         for (let x = site.cx - site.hw - site.blend; x <= site.cx + site.hw + site.blend; x++) {
202:           if (x < -HX || x >= HX || z < -HZ || z >= HZ) continue;
203:           const dx = Math.max(site.cx - site.hw - x, 0, x - (site.cx + site.hw));
204:           const dz = Math.max(site.cz - site.hd - z, 0, z - (site.cz + site.hd));
205:           const d = Math.max(dx, dz);
206:           if (d <= 0) this.heights[this.hidx(x, z)] = site.target;
207:           else if (d <= site.blend) this.heights[this.hidx(x, z)] = Math.round(lerp(site.target, this.heights[this.hidx(x, z)], smooth(d / site.blend)));
208:         }
209:       }
210:     }
211:     this.siteList = Object.values(sites);
212:     this.village = sites.village;
213:     this.castle = sites.castle;
214:     this.ruins = sites.ruins;
215:     this.stones = sites.stones;
216:     this.camp = sites.camp;
217:   }
