76: class Particles {
77:   constructor(scene, count, additive = false) {
78:     this.count = count;
79:     this.cursor = 0;
80:     this.pos = new Float32Array(count * 3);
81:     this.col = new Float32Array(count * 3);
82:     this.size = new Float32Array(count);
83:     this.alpha = new Float32Array(count);
84:     this.vel = new Float32Array(count * 3);
85:     this.life = new Float32Array(count);
86:     this.maxLife = new Float32Array(count);
87:     this.gravity = new Float32Array(count);
88:     this.drag = new Float32Array(count);
89:     this.baseSize = new Float32Array(count);
90:     const g = new THREE.BufferGeometry();
91:     g.setAttribute('position', new THREE.BufferAttribute(this.pos, 3).setUsage(THREE.DynamicDrawUsage));
92:     g.setAttribute('color', new THREE.BufferAttribute(this.col, 3).setUsage(THREE.DynamicDrawUsage));
93:     g.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1).setUsage(THREE.DynamicDrawUsage));
94:     g.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1).setUsage(THREE.DynamicDrawUsage));
95:     this.geometry = g;
96:     const material = new THREE.ShaderMaterial({
97:       uniforms: { uMap: { value: new THREE.CanvasTexture(makeParticleTexture()) } },
98:       vertexShader: `
99:         attribute float aSize; attribute float aAlpha;
100:         varying vec3 vColor; varying float vAlpha;
101:         void main() {
102:           vColor = color; vAlpha = aAlpha;
103:           vec4 mv = modelViewMatrix * vec4(position, 1.0);
104:           gl_PointSize = aSize * (300.0 / max(0.1, -mv.z));
105:           gl_Position = projectionMatrix * mv;
106:         }`,
107:       fragmentShader: `
108:         uniform sampler2D uMap;
109:         varying vec3 vColor; varying float vAlpha;
110:         void main() {
111:           vec4 tex = texture2D(uMap, gl_PointCoord);
112:           float a = tex.a * vAlpha;
113:           if (a < 0.01) discard;
114:           gl_FragColor = vec4(vColor, a);
115:         }`,
116:       transparent: true,
117:       depthWrite: false,
118:       vertexColors: true,
119:       blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
120:     });
121:     this.points = new THREE.Points(g, material);
122:     this.points.frustumCulled = false;
123:     scene.add(this.points);
124:   }
125: 
126:   spawn(x, y, z, color, opts = {}) {
127:     const i = this.cursor++ % this.count;
128:     const c = new THREE.Color(color);
129:     this.pos[i * 3] = x; this.pos[i * 3 + 1] = y; this.pos[i * 3 + 2] = z;
130:     this.col[i * 3] = c.r; this.col[i * 3 + 1] = c.g; this.col[i * 3 + 2] = c.b;
131:     const speed = opts.speed ?? 2;
132:     this.vel[i * 3] = (Math.random() - 0.5) * speed;
133:     this.vel[i * 3 + 1] = (opts.up ?? 1) + Math.random() * speed * 0.7;
134:     this.vel[i * 3 + 2] = (Math.random() - 0.5) * speed;
135:     this.life[i] = this.maxLife[i] = opts.life ?? 0.8;
136:     this.gravity[i] = opts.gravity ?? -7;
137:     this.drag[i] = opts.drag ?? 0.94;
138:     this.baseSize[i] = opts.size ?? 0.12;
139:     this.size[i] = this.baseSize[i];
140:     this.alpha[i] = 1;
141:   }
142: 
143:   update(dt) {
144:     for (let i = 0; i < this.count; i++) {
145:       if (this.life[i] <= 0) { this.alpha[i] = 0; continue; }
146:       this.life[i] -= dt;
147:       const p = i * 3;
148:       this.vel[p + 1] += this.gravity[i] * dt;
149:       this.vel[p] *= this.drag[i];
150:       this.vel[p + 1] *= this.drag[i];
151:       this.vel[p + 2] *= this.drag[i];
152:       this.pos[p] += this.vel[p] * dt;
153:       this.pos[p + 1] += this.vel[p + 1] * dt;
154:       this.pos[p + 2] += this.vel[p + 2] * dt;
155:       const t = clamp(this.life[i] / this.maxLife[i], 0, 1);
156:       this.alpha[i] = t;
157:       this.size[i] = this.baseSize[i] * (0.5 + t * 0.5);
158:     }
159:     this.geometry.attributes.position.needsUpdate = true;
160:     this.geometry.attributes.color.needsUpdate = true;
161:     this.geometry.attributes.aSize.needsUpdate = true;
162:     this.geometry.attributes.aAlpha.needsUpdate = true;
163:   }
164: }
