219:   fillTerrain() {
220:     for (let z = -HZ; z < HZ; z++) for (let x = -HX; x < HX; x++) {
221:       const h = this.heights[this.hidx(x, z)];
222:       const beach = h <= SEA_LEVEL + 1;
223:       const high = h > 22;
224:       for (let y = 0; y <= h; y++) {
225:         let id = B.STONE;
226:         if (y > h - 4) id = B.DIRT;
227:         if (y === h) id = beach ? B.SAND : high ? (h > 27 ? B.STONE_DARK : B.STONE) : B.GRASS;
228:         this.setRaw(x, y, z, id);
229:       }
230:       if (h < SEA_LEVEL) {
231:         for (let y = h + 1; y <= SEA_LEVEL; y++) this.setRaw(x, y, z, B.WATER);
232:         if (h > SEA_LEVEL - 2) this.setRaw(x, h, z, B.SAND);
233:       }
234:     }
