393:   buildDecorMeshes(scene) {
394:     const makeGeometry = (tile) => {
395:       const uv = tileUV(tile);
396:       const positions = [
397:         -0.5, 0, 0, 0.5, 0, 0, 0.5, 1, 0, -0.5, 1, 0,
398:         0, 0, -0.5, 0, 0, 0.5, 0, 1, 0.5, 0, 1, -0.5,
399:       ];
400:       const uvs = [];
401:       for (let i = 0; i < 2; i++) {
402:         uvs.push(uv.x0, uv.y0, uv.x1, uv.y0, uv.x1, uv.y1, uv.x0, uv.y1);
403:       }
404:       const indices = [0, 1, 2, 0, 2, 3, 4, 5, 6, 4, 6, 7];
405:       const g = new THREE.BufferGeometry();
406:       g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
407:       g.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
408:       g.setIndex(indices);
409:       g.computeVertexNormals();
410:       return g;
411:     };
412:     const mat = new THREE.MeshLambertMaterial({ map: this.atlas, alphaTest: 0.45, side: THREE.DoubleSide });
413:     const dummy = new THREE.Object3D();
414:     for (const type of ['tuft', 'flower']) {
415:       const list = this.decorations.filter((d) => d.type === type);
416:       if (!list.length) continue;
417:       const geo = makeGeometry(type === 'flower' ? TILE.FLOWER : TILE.GRASS_TUFT);
418:       const mesh = new THREE.InstancedMesh(geo, mat, list.length);
419:       mesh.frustumCulled = false;
420:       list.forEach((d, i) => {
421:         dummy.position.set(d.x, d.y, d.z);
422:         dummy.rotation.set(0, d.rot, 0);
423:         dummy.scale.set(d.scale, d.scale * (type === 'flower' ? 0.9 : 1.0), d.scale);
424:         dummy.updateMatrix();
425:         mesh.setMatrixAt(i, dummy.matrix);
426:       });
427:       mesh.instanceMatrix.needsUpdate = true;
428:       mesh.receiveShadow = true;
429:       this.group.add(mesh);
430:       this.decorMeshes.push(mesh);
431:     }
432:   }
