233:     for (const t of this.world.torches) {
234:       if (t.campfire) continue;
235:       const g = new THREE.Group();
236:       g.position.set(t.x, t.y, t.z);
237:       const stick = box(0.08, 0.62, 0.08, '#5b3f22', 0, -0.31, 0);
238:       stick.rotation.z = 0.12;
239:       g.add(stick);
240:       const flame = new THREE.Sprite(glowMat.clone());
241:       flame.scale.set(0.7, 0.9, 1);
242:       flame.position.y = 0.08;
243:       g.add(flame);
244:       const core = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color: 0xfff0b0, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending }));
245:       core.scale.set(0.25, 0.4, 1);
246:       core.position.y = 0.12;
247:       g.add(core);
