266:       for (let i = 0; i < 6; i++) {
267:         const a = (i / 6) * TAU;
268:         const log = box(0.55, 0.12, 0.14, '#5b3f22', Math.cos(a) * 0.38, 0.1, Math.sin(a) * 0.38);
269:         log.rotation.y = -a;
270:         log.rotation.z = 0.18;
271:         g.add(log);
272:       }
273:       const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color: 0xff9d3c, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending }));
274:       glow.scale.set(1.7, 1.8, 1);
275:       glow.position.y = 0.55;
276:       g.add(glow);
277:       const core = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color: 0xffe6a0, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending }));
278:       core.scale.set(0.55, 0.9, 1);
279:       core.position.y = 0.45;
280:       g.add(core);
281:       if (this.lightBudget > 0) {
