283:         light.position.y = 0.7;
284:         g.add(light);
285:         this.lightBudget--;
286:       }
287:       g.userData.glow = glow;
288:       g.userData.core = core;
289:       g.userData.fire = c;
290:       this.campfires.push(g);
291:       this.scene.add(g);
