80:   isSolidAt(x, y, z) { return isSolid(this.getBlock(x, y, z)); }
81:   isWaterAt(x, y, z) { return isWater(this.getBlock(x, y, z)); }
82:   heightAt(x, z) {
83:     x = Math.floor(x); z = Math.floor(z);
84:     if (x < -HX || x >= HX || z < -HZ || z >= HZ) return SEA_LEVEL;
85:     return this.heights[this.hidx(x, z)];
