97:   clearBox(x0, y0, z0, x1, y1, z1) {
98:     for (let y = y0; y <= y1; y++) for (let z = z0; z <= z1; z++) for (let x = x0; x <= x1; x++) this.setBlock(x, y, z, B.AIR, false);
99:   }
