172:   const hair = box(0.38, 0.12, 0.36, colors.hair || '#4a3826', 0, 1.8, 0);
173:   const armL = box(0.15, 0.58, 0.16, robe, -0.37, 1.12, 0);
174:   const armR = box(0.15, 0.58, 0.16, robe, 0.37, 1.12, 0);
175:   const legL = box(0.19, 0.52, 0.22, colors.legs || '#3a3025', -0.15, 0.29, 0);
176:   const legR = box(0.19, 0.52, 0.22, colors.legs || '#3a3025', 0.15, 0.29, 0);
