69:     ctx.fillStyle = ratio > 0.5 ? '#b53a2a' : '#d18a2e';
70:     roundRect(ctx, 5, 7, 150 * clamp(ratio, 0, 1), 10, 3); ctx.fill();
71:     tex.needsUpdate = true;
72:   };
73:   return { sprite, draw };
74: }
