402:   entityBlocked(x, y, z) {
403:     return this.world.isSolidAt(x, y, z) || this.world.isSolidAt(x, y + 1, z);
404:   }
405: 
406:   moveGround(g, dx, dz) {
407:     const w = this.world;
408:     const tryAxis = (ax, az) => {
409:       const nx = g.position.x + ax, nz = g.position.z + az;
410:       const gy = w.groundY(nx, nz);
411:       if (Math.abs(gy - g.position.y) > 1.25) return false;
412:       if (this.entityBlocked(nx, gy, nz)) return false;
413:       g.position.x = nx; g.position.z = nz; g.position.y = gy;
414:       return true;
415:     };
416:     if (!tryAxis(dx, dz)) { tryAxis(dx, 0); tryAxis(0, dz); }
417:   }
418: 
419:   update(dt, player, game) {
420:     this.time += dt;
421:     const pp = player.position;
422:     for (const g of this.npcs) {
423:       const n = g.userData.npc;
424:       const dx = pp.x - g.position.x, dz = pp.z - g.position.z;
425:       const dist = Math.hypot(dx, dz);
426:       g.userData.label.visible = dist < 11;
427:       g.position.y = g.userData.baseY + Math.sin(this.time * 1.4 + g.userData.phase) * 0.012;
428:       if (dist < 5) {
429:         const target = Math.atan2(dx, dz);
430:         let diff = ((target - g.rotation.y + Math.PI * 3) % TAU) - Math.PI;
431:         g.rotation.y += diff * Math.min(1, dt * 2.2);
432:       }
433:       const parts = g.userData.parts;
434:       parts.armL.rotation.x = Math.sin(this.time * 1.1 + g.userData.phase) * 0.06;
435:       parts.armR.rotation.x = -Math.sin(this.time * 1.1 + g.userData.phase) * 0.06;
436:     }
437: 
438:     for (const g of this.enemies) {
439:       if (g.userData.dead) {
440:         g.userData.deadTimer += dt;
441:         g.rotation.z = Math.min(Math.PI / 2, g.userData.deadTimer * 3.5);
442:         g.position.y = g.userData.baseY - Math.max(0, (g.userData.deadTimer - 1) * 0.5);
443:         g.visible = g.userData.deadTimer < 2.6;
444:         continue;
445:       }
446:       const e = g.userData.enemy;
447:       const dx = pp.x - g.position.x, dz = pp.z - g.position.z;
448:       const dist = Math.hypot(dx, dz);
449:       g.userData.attackCd = Math.max(0, g.userData.attackCd - dt);
450:       g.userData.attackAnim = Math.max(0, g.userData.attackAnim - dt);
451:       const speed = e.boss ? 1.7 : 2.25;
452:       if (dist < (e.boss ? 16 : 13) && dist > 1.35) {
453:         const len = Math.max(0.0001, dist);
454:         const step = speed * dt;
455:         this.moveGround(g, (dx / len) * step, (dz / len) * step);
456:         const target = Math.atan2(dx, dz);
457:         let diff = ((target - g.rotation.y + Math.PI * 3) % TAU) - Math.PI;
458:         g.rotation.y += diff * Math.min(1, dt * 6);
459:       } else if (dist >= 13) {
460:         const wd = g.userData.wander;
461:         wd.timer -= dt;
462:         if (wd.timer <= 0) {
463:           wd.timer = 2 + Math.random() * 4;
464:           const a = Math.random() * TAU, r = Math.random() * (e.radius || 5);
465:           wd.x = e.home.x + Math.cos(a) * r;
466:           wd.z = e.home.z + Math.sin(a) * r;
467:         }
468:         const wx = wd.x - g.position.x, wz = wd.z - g.position.z;
469:         const wl = Math.hypot(wx, wz);
470:         if (wl > 0.4) {
471:           this.moveGround(g, (wx / wl) * speed * 0.42 * dt, (wz / wl) * speed * 0.42 * dt);
472:           const target = Math.atan2(wx, wz);
473:           let diff = ((target - g.rotation.y + Math.PI * 3) % TAU) - Math.PI;
474:           g.rotation.y += diff * Math.min(1, dt * 3);
475:         }
476:       }
477:       if (dist < 1.85 && g.userData.attackCd <= 0) {
478:         g.userData.attackCd = e.boss ? 1.35 : 1.6;
479:         g.userData.attackAnim = 0.35;
480:         const dmg = e.boss ? 22 : 10;
481:         player.takeDamage(dmg, g.position);
482:         game.audio.play('hurt');
483:         game.flashDamage();
484:       }
485:       const parts = g.userData.parts;
486:       const walk = Math.min(1, dist > 1.35 ? 1 : 0);
487:       const swing = Math.sin(this.time * 8 + g.userData.phase) * 0.5 * walk;
488:       parts.legL.rotation.x = swing;
489:       parts.legR.rotation.x = -swing;
490:       parts.armL.rotation.x = -swing * 0.7;
491:       parts.armR.rotation.x = g.userData.attackAnim > 0 ? -1.8 * Math.sin((g.userData.attackAnim / 0.35) * Math.PI) : swing * 0.7;
492:       const hp = g.userData.hp / g.userData.maxHp;
493:       g.userData.healthSprite.sprite.visible = e.boss || hp < 1 || dist < 9;
494:       g.userData.healthSprite.sprite.position.y = 2.35;
495:     }
496: 
497:     for (const g of this.shards) {
498:       if (g.userData.collected) continue;
499:       g.rotation.y += dt * 1.2;
500:       g.position.y = g.userData.shard.y + Math.sin(this.time * 2 + g.userData.shard.x) * 0.1;
