46: function roundRect(ctx, x, y, w, h, r) {
47:   ctx.beginPath();
48:   ctx.moveTo(x + r, y);
49:   ctx.arcTo(x + w, y, x + w, y + h, r);
50:   ctx.arcTo(x + w, y + h, x, y + h, r);
51:   ctx.arcTo(x, y + h, x, y, r);
52:   ctx.arcTo(x, y, x + w, y, r);
53:   ctx.closePath();
54: }
