237:   paintColumn(x, z, id = B.PATH, clear = 2) {
238:     if (x < -HX || x >= HX || z < -HZ || z >= HZ) return;
239:     const h = this.heights[this.hidx(x, z)];
240:     if (h <= SEA_LEVEL) return;
241:     this.setRaw(x, h, z, id);
242:     for (let k = 1; k <= clear; k++) this.setRaw(x, h + k, z, B.AIR);
243:   }
