346:   createMaterials() {
347:     const canvas = getAtlasCanvas();
348:     this.atlas = new THREE.CanvasTexture(canvas);
349:     this.atlas.colorSpace = THREE.SRGBColorSpace;
350:     this.atlas.magFilter = THREE.NearestFilter;
351:     this.atlas.minFilter = THREE.NearestFilter;
352:     this.atlas.generateMipmaps = false;
353:     this.material = new THREE.MeshLambertMaterial({ map: this.atlas, vertexColors: true });
354: 
355:     const wc = document.createElement('canvas');
356:     wc.width = 16; wc.height = 16;
357:     const src = tileSourceRect(TILE.WATER);
358:     wc.getContext('2d').drawImage(canvas, src.sx, src.sy, src.sw, src.sh, 0, 0, 16, 16);
359:     this.waterTexture = new THREE.CanvasTexture(wc);
360:     this.waterTexture.colorSpace = THREE.SRGBColorSpace;
361:     this.waterTexture.wrapS = THREE.RepeatWrapping;
362:     this.waterTexture.wrapT = THREE.RepeatWrapping;
363:     this.waterTexture.magFilter = THREE.NearestFilter;
364:     this.waterTexture.minFilter = THREE.LinearMipmapLinearFilter;
365:     this.waterMaterial = new THREE.MeshStandardMaterial({
366:       map: this.waterTexture, transparent: true, opacity: 0.82,
367:       roughness: 0.22, metalness: 0.06, depthWrite: false, side: THREE.DoubleSide,
368:     });
